/**
 * Check if a given object implements the IncomeStatementItemDepreciation interface.
 */
export function instanceOfIncomeStatementItemDepreciation(value) {
    return true;
}
export function IncomeStatementItemDepreciationFromJSON(json) {
    return IncomeStatementItemDepreciationFromJSONTyped(json, false);
}
export function IncomeStatementItemDepreciationFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        reconciledDepreciation: json["reconciled_depreciation"] == null
            ? undefined
            : json["reconciled_depreciation"],
    };
}
export function IncomeStatementItemDepreciationToJSON(json) {
    return IncomeStatementItemDepreciationToJSONTyped(json, false);
}
export function IncomeStatementItemDepreciationToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        reconciled_depreciation: value["reconciledDepreciation"],
    };
}
